/* Real drawer controls with opt-in structures generated by the native parser. */
import assert from 'node:assert/strict';
import { readFileSync, mkdirSync, writeFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { launchBrowser } from './browser.mjs';
import { captureFailure } from './diagnostics.mjs';

const fixture = JSON.parse(readFileSync(new URL('./fixtures/java-traces.json', import.meta.url), 'utf8'));
const samples = fixture.cases, complete = samples.find(item => item.detail.trace.complete), incomplete = samples.find(item => !item.detail.trace.complete);
assert.ok(complete && incomplete, 'actual-parser fixtures include complete and incomplete structures');
assert.ok(complete.detail.trace.nodes.some(node => node.frameCount > 20), 'native sample exercises frame pagination');
const output = resolve('output/playwright'); mkdirSync(output, { recursive: true });
const browser = await launchBrowser(), page = await browser.newPage({ viewport: { width: 1440, height: 960 }, reducedMotion: 'reduce' });
await page.addInitScript(cases => { window.__mockJavaFixturesEnabled = true; window.__mockJavaFixtures = cases; }, samples);
page.setDefaultTimeout(20000); const errors = [], results = { parserCommit: fixture.parserCommit, transport: 'Opt-in preview with actual-parser serialized structures' };
let phase = 'startup'; page.on('pageerror', error => errors.push(error.message));
const settled = async () => { await page.evaluate(() => settleFilterTabCounts()); await page.waitForFunction(() => Tasks.pending() === 0); };
const calls = () => page.evaluate(() => ({ ...window.__mockCommandCalls }));
const openFixture = async sample => {
  const row = await page.evaluate(name => window.__mockJavaFixtureRows.find(item => item.name === name), sample.name);
  const tableRow = page.locator(`#events-table tbody tr[data-event-id="${row.id}"]`);
  await tableRow.locator('td[data-column="message"]').click();
  await page.waitForFunction(id => state.currentDetailEv?.id === id && state.detailAdmission && !document.querySelector('#drawer').hidden, row.id);
  await settled(); return row;
};
try {
  await page.goto(process.argv[2] || 'http://127.0.0.1:4174');
  await page.waitForFunction(() => window.WorkspaceContext?.ready && !WorkspaceContext.changing && state.loaded && !state.loadOverlay);
  await page.getByRole('button', { name: 'Explorar', exact: true }).click();
  await page.waitForFunction(() => explorerAnalytics.get(explorerKey())?.status === 'done' && document.querySelector('#events-table').getAttribute('aria-busy') === 'false');
  await page.evaluate(() => {
    state.visibleCols = ['timestamp', 'level', 'source', 'message']; renderTable({ total: state.total, rows: state.rows }, { reuseRows: true });
    window.__javaCopied = [];
    Object.defineProperty(navigator, 'clipboard', { configurable: true, value: { writeText: async value => { window.__javaCopied.push(value); } } });
  });
  phase = 'collapsed native structure'; const row = await openFixture(complete);
  assert.equal(await page.locator('.java-trace').getAttribute('open'), null);
  assert.equal(await page.locator('.java-trace-node,.java-trace-frame').count(), 0);
  assert.equal((await calls()).java_trace_detail || 0, 0, 'paging and opening detail do not load rich traces');
  assert.equal(await page.evaluate(() => state.rows.every(row => !Object.hasOwn(row, 'javaTrace') && !Object.hasOwn(row.fields, 'java.trace')) && !Object.hasOwn(state.currentDetailEv, 'javaTrace') && !Object.hasOwn(state.currentDetailEv.fields, 'java.trace')), true);
  const before = await calls();
  await page.locator('.java-trace-summary').click();
  await page.locator('.java-trace-node').first().waitFor();
  assert.equal((await calls()).java_trace_detail, 1, 'first expansion performs one owner-bound detail read');
  results.traceRequest = await page.evaluate(() => window.__mockRequests.findLast(item => item.cmd === 'java_trace_detail'));
  assert.equal(results.traceRequest.id, row.id); assert.equal(results.traceRequest.eventRef, row.eventRef);
  assert.ok(results.traceRequest.operationId); assert.ok(results.traceRequest.analysisContext); assert.ok(Number.isSafeInteger(results.traceRequest.sourceGeneration));
  assert.equal(results.traceRequest.hasCaseEvents, false);
  const expandedCalls = await calls();
  assert.equal(await page.locator('.java-trace-node').count(), Math.min(8, complete.detail.trace.nodes.length));
  assert.equal(await page.locator('.java-trace-frame').count(), 0);
  const frameNodeIndex = complete.detail.trace.nodes.findIndex(node => node.frameCount > 20), node = page.locator(`.java-trace-node[data-node="${frameNodeIndex}"]`);
  await node.locator('summary').click();
  // HTML details dispatches toggle in a queued task. Wait for the exact lazy
  // batch, then keep the strict count check; clicking alone is not completion.
  await page.waitForFunction(index => document.querySelector(`.java-trace-node[data-node="${index}"]`)?.querySelectorAll('.java-trace-frame').length === 20, frameNodeIndex);
  assert.equal(await node.locator('.java-trace-frame').count(), 20);
  assert.match(await node.locator('.java-trace-count').textContent(), new RegExp(`20 de ${complete.detail.trace.nodes[frameNodeIndex].frameCount} frames`));
  await node.getByRole('button', { name: 'Mostrar mais frames', exact: true }).click();
  assert.equal(await node.locator('.java-trace-frame').count(), Math.min(40, complete.detail.trace.nodes[frameNodeIndex].frameCount));
  await node.locator('summary').click(); await node.locator('summary').click();
  assert.deepEqual(await calls(), expandedCalls, 'node expansion/pagination never queries or reparses the dataset');
  await page.locator('.java-trace-summary').click(); await page.locator('.java-trace-summary').click();
  assert.equal((await calls()).java_trace_detail, 1, 'reopening reuses only this captured detail response');
  results.localExpansion = { before, after: await calls(), frames: await node.locator('.java-trace-frame').count() };
  await page.screenshot({ path: resolve(output, 'java-trace-complete-dark-1440.png') });

  phase = 'real scalar canonical actions';
  for (const column of ['java.exception.class', 'java.root_cause.class', 'java.trace.fingerprint']) {
    assert.equal(typeof complete.fields[column], 'string');
    await page.locator(`.java-trace-scalar-value[data-column="${column}"]`).click({ button: 'right' });
    await page.getByRole('menuitem', { name: `Criar filtro: ${column}`, exact: true }).click();
    await page.waitForFunction(() => !document.querySelector('#filter-pop').hidden);
    assert.equal(await page.locator('#fp-col').inputValue(), column); assert.equal(await page.locator('#fp-val').inputValue(), complete.fields[column]);
    const request = await page.evaluate(() => window.__mockRequests.findLast(item => item.cmd === 'analysis_field_text'));
    assert.equal(request.column, column); assert.equal(request.id, row.id); assert.equal(request.eventRef, row.eventRef);
    await page.locator('#fp-cancel').click();
  }
  phase = 'virtual frames and original decoded text';
  const exactReads = (await calls()).analysis_field_text;
  await node.locator('.java-trace-node-title').click({ button: 'right' });
  const labels = await page.locator('.ctx-menu button').allTextContents();
  assert.ok(labels.some(label => label.includes('Copiar classe observada')));
  assert.ok(labels.every(label => !/filtr|Timeline|Transformar/i.test(label)), 'virtual node parts never acquire invented field actions');
  await page.getByRole('button', { name: 'Copiar classe observada', exact: true }).click();
  await page.waitForFunction(() => window.__javaCopied.length === 1);
  assert.equal(await page.evaluate(() => window.__javaCopied[0]), complete.detail.trace.nodes[frameNodeIndex].class);
  assert.equal((await calls()).analysis_field_text, exactReads);
  await page.locator('.java-trace-source').click();
  assert.equal(await page.locator('#pane-raw').isVisible(), true); assert.equal(await page.locator('#pane-raw').textContent(), complete.raw);
  await page.getByRole('button', { name: 'Visão geral', exact: true }).click();

  phase = 'exact scalar filter';
  const column = 'java.trace.fingerprint', fingerprint = complete.fields[column];
  await page.locator(`.java-trace-scalar-value[data-column="${column}"]`).click({ button: 'right' });
  await page.getByRole('menuitem', { name: `Criar filtro: ${column}`, exact: true }).click(); await page.locator('#fp-apply').click();
  await page.waitForFunction(value => state.total === 1 && state.rows.length === 1 && state.rows[0].fields['java.trace.fingerprint'] === value, fingerprint);
  results.scalarFilter = await page.evaluate(() => ({ filters: state.filters, eventRef: state.rows[0].event_ref }));
  assert.equal(results.scalarFilter.eventRef, row.eventRef);
  await page.evaluate(() => closeDrawer()); await page.locator('#btn-clear-filters').click();
  await page.waitForFunction(() => state.total === 6000 && document.querySelector('#events-table').getAttribute('aria-busy') === 'false');

  phase = 'incomplete structure'; await openFixture(incomplete);
  await page.locator('.java-trace-summary').click();
  await page.locator('.java-trace-diagnostics').waitFor();
  assert.match(await page.locator('.java-trace-status').textContent(), /interpretação incompleta/);
  assert.ok(await page.locator('.java-trace-diagnostics li').count() > 0);
  assert.equal(await page.locator('.java-trace-scalar-value[data-column="java.root_cause.class"],.java-trace-scalar-value[data-column="java.trace.fingerprint"]').count(), 0);
  for (const summary of await page.locator('.java-trace-node-title').all()) await summary.click();
  await page.waitForFunction(expected => [...document.querySelectorAll('.java-trace-node')].every((node, index) =>
    node.open && node.querySelectorAll('.java-trace-frame').length === Math.min(20, expected[index])), incomplete.detail.trace.nodes.map(node => node.frameCount));
  await page.setViewportSize({ width: 1024, height: 768 }); await page.evaluate(() => { document.documentElement.dataset.theme = 'light'; });
  assert.equal(await page.evaluate(() => document.documentElement.scrollWidth > innerWidth), false);
  await page.screenshot({ path: resolve(output, 'java-trace-incomplete-light-1024.png') });
  await page.locator('.java-trace-source').click(); assert.equal(await page.locator('#pane-raw').textContent(), incomplete.raw);
  results.incomplete = { diagnostics: incomplete.detail.trace.diagnostics.map(item => item.code), rawPreserved: true };
  assert.deepEqual(errors, []);
  writeFileSync(resolve(output, 'java-trace.json'), JSON.stringify({ results, errors }, null, 2));
  console.log(JSON.stringify({ results, errors }, null, 2));
} catch (error) {
  await captureFailure(page, 'java-trace', error, { phase, errors }); throw error;
} finally { await browser.close(); }
